gA9(){return"1. \ud50c\ub79c"},
gA8(){return"\uc624\ub298 \ud560 \uc218 \uc788\ub294 \uc591(\uccab \ud14c\uc2a4\ud2b8)\uc5d0\uc11c \uc2dc\uc791\ud574 \ubaa9\ud45c\uc77c\uae4c\uc9c0 \uc870\uae08\uc529 \ubaa9\ud45c\ub85c \uc62c\ub77c\uac00\uc694. \uc26c\ub294 \ub0a0\uc740 \uc9c1\uc811 \uace8\ub77c\uc694. \ub9e4 \uc6b4\ub3d9\uc77c\uc740 \uc6b4\ub3d9\uc5d0 \ub9de\ub294 \ubc29\uc2dd\uc73c\ub85c \uc138\ud2b8\uac00 \ub098\ub258\uc5b4\uc694. \uadf8\ub0a0 \ubaa9\ud45c\uae4c\uc9c0 \uc62c\ub9ac\ub294 \uc6cc\ubc0d\uc5c5 \uc138\ud2b8, \uac19\uc740 \uc591\uc758 \uc138\ud2b8, \ud53c\ub77c\ubbf8\ub4dc, \ub2ec\ub9ac\uae30\ub77c\uba74 \ud55c \ubc88\uc758 \uc5f0\uc18d \ub2ec\ub9ac\uae30\uc608\uc694."},
gAd(){return"2. \uc548\uc804 \ud55c\ub3c4"},
gAc(){return"\ubd80\ud558\ub294 \ud55c \uc8fc\uc5d0 \ucd5c\ub300 \uc57d 15%\uae4c\uc9c0\ub9cc \ub298\uc5b4\uc694. \ub354 \ube68\ub9ac \ub298\ub824\uc57c \ud558\ub294 \ub0a0\uc9dc\ub97c \uace0\ub974\uba74 \ub0a0\uc9dc\ub97c \ub4a4\ub85c \ubbf8\ub8e8\uace0, \uc55e\ub2f9\uae30\uc9c0\ub294 \uc54a\uc544\uc694. 4\uc8fc\ub9c8\ub2e4 \ud55c \uc8fc\ub294 60%\ub85c \ub0ae\ucdb0 \ud68c\ubcf5\ud558\ub294\ub370, \ub9c8\uc9c0\ub9c9 \uc8fc\ub294 \uc608\uc678\ub77c \ucd5c\uc0c1\uc758 \uc0c1\ud0dc\ub85c \ubaa9\ud45c\uc5d0 \ub3c4\ub2ec\ud574\uc694. \ub098\uc774, \ud0a4, \uccb4\uc911, \ud65c\ub3d9 \uc218\uc900\uc744 \uc54c\ub824 \uc8fc\uba74 \ud398\uc774\uc2a4\uac00 \ub354 \uc2e0\uc911\ud574\uc9c8 \uc218 \uc788\uc5b4\uc694."},
